urlset:
{% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% if url.item.images %}
      {% for img in url.item.images.all %}
        {% if img.image %}

          https://{{ request.get_host }}{{ img.image.url }}
          {{ url.item.name }}


        {% endif %}
      {% endfor %}
    {% endif %}

{% endfor %}
{% endspaceless %}
